func WithUnaryOptions(opts ...UnaryOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryOptions(%d options)", len(opts)))
		for _, opt := range opts {
			opt.F(o, di)
		}
	}}
}

// WithUnaryRPCTimeout sets the RPC timeout specifically for unary calls.
// This timeout applies to the entire unary request-response cycle.
func WithUnaryRPCTimeout(d time.Duration) UnaryOption {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryRPCTimeout(%s)", d))
		o.Configs = rpcinfo.AsMutableRPCConfig(o.Configs).SetRPCTimeout(d)
	}}
}

// WithUnaryConnectTimeout sets the connection timeout for unary RPC calls.
func WithUnaryConnectTimeout(d time.Duration) UnaryOption {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryConnectTimeout(%s)", d))
		o.Configs = rpcinfo.AsMutableRPCConfig(o.Configs).SetConnectTimeout(d)
	}}
}

// WithUnaryMiddleware adds middleware specifically for unary RPC calls.
// The middleware will only be applied to unary operations.
func WithUnaryMiddleware(mw endpoint.Middleware) UnaryOption {
	mwb := func(ctx context.Context) endpoint.Middleware {
		return mw
	}
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddleware(%+v)", utils.GetFuncName(mw)))
		o.MWBs = append(o.MWBs, mwb)
	}}
}

// WithUnaryMiddlewareBuilder adds a context-dependent middleware builder for unary calls.
func WithUnaryMiddlewareBuilder(mwb endpoint.MiddlewareBuilder) UnaryOption {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddlewareBuilder(%+v)", utils.GetFuncName(mwb)))
		o.MWBs = append(o.MWBs, mwb)
	}}
}

// WithUnaryFailureRetry sets the failure retry policy for unary calls.
// The retry policy will take effect for all unary methods.
func WithUnaryFailureRetry(p *retry.FailurePolicy) UnaryOption {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		if p == nil {
			return
		}
		di.Push(fmt.Sprintf("WithUnaryFailureRetry(%+v)", p))
		if o.RetryMethodPolicies == nil {
			o.RetryMethodPolicies = make(map[string]retry.Policy)
		}
		if o.RetryMethodPolicies[retry.Wildcard].MixedPolicy != nil ||
			o.RetryMethodPolicies[retry.Wildcard].BackupPolicy != nil {
			panic("MixedPolicy or BackupPolicy has been setup, cannot support Failure Retry at same time")
		}
		o.RetryMethodPolicies[retry.Wildcard] = retry.BuildFailurePolicy(p)
	}}
}

// WithUnaryBackupRequest sets the backup request policy for unary calls.
func WithUnaryBackupRequest(p *retry.BackupPolicy) UnaryOption {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		if p == nil {
			return
		}
		di.Push(fmt.Sprintf("WithUnaryBackupRequest(%+v)", p))
		if o.RetryMethodPolicies == nil {
			o.RetryMethodPolicies = make(map[string]retry.Policy)
		}
		if o.RetryMethodPolicies[retry.Wildcard].MixedPolicy != nil ||
			o.RetryMethodPolicies[retry.Wildcard].FailurePolicy != nil {
			panic("MixedPolicy or FailurePolicy has been setup, cannot support Backup Request at same time")
		}
		o.RetryMethodPolicies[retry.Wildcard] = retry.BuildBackupRequest(p)
	}}
}

// WithUnaryRetryMethodPolicies sets the retry policy for specific unary methods.
// The priority is higher than WithUnaryFailureRetry and WithUnaryBackupRequest.
// Notice: method name is case-sensitive.
func WithUnaryRetryMethodPolicies(mp map[string]retry.Policy) UnaryOption {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		if mp == nil {
			return
		}
		di.Push(fmt.Sprintf("WithUnaryRetryMethodPolicies(%+v)", mp))
		if o.RetryMethodPolicies == nil {
			o.RetryMethodPolicies = make(map[string]retry.Policy)
		}
		for method, policy := range mp {
			o.RetryMethodPolicies[method] = policy
		}
	}}
}

