// Close is to release resource of ConnPool, it is executed when client is closed.
func (p *connPool) Close() error {
	p.conns.Range(func(addr, trans interface{}) bool {
		p.conns.Delete(addr)
		trans.(*transports).close()
		return true
	})
	return nil
}

// Dump returns a snapshot of the connection pool state for debugging.
// Returns a map where keys are remote addresses and values are slices of transport dump results.
// This method is panic-safe and will recover from any panics, logging errors instead.
func (p *connPool) Dump() interface{} {
	defer func() {
		if r := recover(); r != nil {
			klog.Errorf("KITEX: panic in connPool.Dump(): %v", r)
		}
	}()

	result := make(map[string]interface{})

	p.conns.Range(func(key, value interface{}) bool {
		addr, ok := key.(string)
		if !ok {
			return true
		}

		trans, ok := value.(*transports)
		if !ok {
			return true
		}

		// Collect dump info from each transport in the pool
		var transportDumps []interface{}
		for i := 0; i < int(trans.size); i++ {
			if cliTransport := trans.cliTransports[i]; cliTransport != nil {
				// Check if transport supports Dump interface
				if dumper, ok := cliTransport.(interface{ Dump() interface{} }); ok {
					transportDumps = append(transportDumps, dumper.Dump())
				}
			}
		}

		result[addr] = transportDumps
		return true
	})

	return result
}

